#include "sfx/application/ftn_wire.hpp"
#include <iostream>
#include <fstream>
#include <stdexcept>
using namespace sfx::application;
namespace {
unsigned checks{};
void check(bool ok,const char* what){++checks;if(!ok)throw std::runtime_error(what);}
void framing(){
    // Independent literal wire bytes, not generated by the serializer under test.
    const std::string input=std::string("\x80\x01\x04\x00\x03",5)+"abc"+std::string("\x80\x04\x00",3)+"SYS";
    for(std::size_t cut=0;cut<=input.size();++cut){BinkpDecoder decoder;std::vector<BinkpFrame> frames;
        const auto receive=[&](BinkpFrame f){frames.push_back(std::move(f));return true;};
        check(decoder.feed(std::string_view(input).substr(0,cut),receive)&&decoder.feed(std::string_view(input).substr(cut),receive),"arbitrary TCP split accepted");
        check(!decoder.pending()&&frames.size()==3&&frames[0].command&&frames[0].id==4&&frames[1].bytes=="abc"&&frames[2].bytes=="SYS","independent frame stream exact");}
    BinkpDecoder incremental;unsigned frames{};for(const auto c:input)check(incremental.feed(std::string_view(&c,1),[&](BinkpFrame){++frames;return true;}),"single-byte socket reads");check(frames==3&&!incremental.pending(),"incremental state drained");
    for(const auto& malformed:{std::string("\x80\x00",2),std::string("\x90\x01",2),std::string("\x80\x04\x02x\0y",6)}){
        BinkpDecoder decoder;check(!decoder.feed(malformed,[](BinkpFrame){return true;})&&decoder.failed(),"malformed command fails bounded decoder");check(!decoder.feed(input,[](BinkpFrame){return true;}),"poisoned decoder cannot be reused");}
    BinkpDecoder semantic;check(!semantic.feed(input,[](BinkpFrame){return false;})&&semantic.failed(),"semantic refusal stops pipeline");
    check(binkp_command(BinkpCommand::ok)==std::string("\x80\x01\x04",3),"OK command exact bytes");
    check(binkp_data("abc")==std::string("\0\3abc",5),"data exact bytes");
    check(binkp_data(std::string(32768,'x')).empty()&&binkp_command(BinkpCommand::nul,std::string(4096,'x')).empty(),"outbound frame limits");
}
void descriptors(){
    for(const auto day:{"su","mo","tu","we","th","fr","sa"})for(const auto sequence:std::string("0123456789abcdefghijklmnopqrstuvwxyz")){
        std::string name="test.";name+=day;name+=sequence;
        check(ftn_message_wire_name(name),"all qualified day/sequence bundle names");
        for(auto& c:name)if(c>='a'&&c<='z')c=static_cast<char>(c-32);
        check(ftn_message_wire_name(name),"case-insensitive bundle naming");
    }
    for(const auto name:{"mail.pkt","MAIL.PKT","00010002.SUZ","0000p001.mo0","nonhex-prefix.fr9"})check(ftn_message_wire_name(name),"qualified bare packet and peer-profile names");
    for(const auto name:{".pkt",".mo0","file.zip","mail.pkt.zip","file.mo00","file.xx0","file.mo-","../file.mo0","dir/file.mo0","file.mo0:ads","CON.mo0","file.mo0 ","file.mo0.","file.mo?"})check(!ftn_message_wire_name(name),"unsafe and lookalike names cannot select message handler");
    const auto file=parse_binkp_file("mail\\x20packet.pkt 123 1730000000 -1",true,true);
    check(file&&file->name=="mail packet.pkt"&&file->size==123&&file->request_offset,"escaped name and NR offer");
    check(file&&format_binkp_file(*file,true)=="mail\\x20packet.pkt 123 1730000000 -1","name escaping exact");
    check(decode_binkp_name("mail\\20packet.pkt")=="mail packet.pkt","historical hex escape accepted");
    for(const auto bad:{"../a","..\\a","C:a","a:stream","a.","a ","CON.pkt","nul","aux .pkt","LPT1.txt","COM9","a/b","..","\\x2e\\x2e\\x2fa","a\\x00b","a\\x1bb","a\\x5cb","a\\x","a\\zz"})check(!decode_binkp_name(bad),"path/device/control/alias file refused");
    for(const auto bad:{"x 18446744073709551616 1 0","x 1073741825 1 0","x -1 1 0","x 1 4294967296 0","x 1 1 2","x 1 1 -2","x 1 1 0 tail","x 1 1"})check(!parse_binkp_file(bad,true,true),"strict bounded numeric descriptor");
    check(!parse_binkp_file("x 1 1 -1",true,false),"NR offset unavailable on 1.0");
    check(parse_binkp_file("x 1 1",false,false).has_value(),"GOT descriptor excludes offset");
    const auto addresses=parse_binkp_addresses("2:200/1@first 2:200/1.2@first");check(addresses&&addresses->size()==2,"point-aware ADR list");
    check(!parse_binkp_addresses("2:200/1@first 2:200/1@first")&&!parse_binkp_addresses("../anything"),"duplicate or malformed ADR refused");
    check(binkp_advertised_system("SYS  Test BBS  ")=="Test BBS","peer system name presentation");
    check(binkp_advertised_system("SYS test\r\nname\x1b")=="test??name?","peer system name cannot inject terminal or log controls");
    check(binkp_advertised_system("VER some program").empty()&&binkp_advertised_system("SYS   ").empty(),"only meaningful advertised system names are shown");
    check(binkp_advertised_system("SYS "+std::string(500,'x')).size()==128,"peer system name is bounded");
    BinkpOptions options;check(observe_binkp_information(options,"VER Independent/1 BINKP/1.1",true)&&options.version11,"explicit VER negotiates1.1");
    BinkpOptions irex;check(observe_binkp_information(irex,"VER Internet Rex 2.29 Win32 (binkp/1.1)",true)&&irex.version11,"actual IREX parenthesized protocol version negotiates1.1");
    check(parse_binkp_file("peer.bin 65537 1793479816 -1",true,irex.version11).has_value(),"actual IREX negotiated NR file request is accepted");
    for(const auto value:{"VER Peer (binkp/1.0)","VER Peer (binkp/1.10)","VER Peer xbinkp/1.1","VER Peer (binkp/1.1","VER Peer binkp/1.1)","SYS (binkp/1.1)"}){BinkpOptions o;check(observe_binkp_information(o,value,true)&&!o.version11,"only complete recognized VER tokens negotiate1.1");}
    check(observe_binkp_information(options,"OPT NR CRAM-SHA1/MD5-0011223344556677 UNKNOWN",true)&&options.request_nr&&options.challenge_hex=="0011223344556677","known options selected unknown ignored");
    check(!observe_binkp_information(options,"OPT CRAM-MD5-0011223344556678",true),"challenge cannot change during handshake");
    BinkpOptions advertised;
    check(observe_binkp_information(advertised,"OPT CRAM-MD5 NR",true)&&advertised.request_nr&&advertised.challenge_hex.empty(),"bare ANetBBS CRAM-MD5 is a capability, not a challenge");
    check(observe_binkp_information(options,"OPT CRAM-MD5",true)&&options.challenge_hex=="0011223344556677","bare CRAM-MD5 leaves a real challenge intact");
    check(!observe_binkp_information(advertised,"OPT CRAM-MD5-",true),"empty challenge still refused");
    BinkpOptions late;check(observe_binkp_information(late,"VER Peer binkp/1.1",false)&&!late.version11,"late VER cannot renegotiate");
    for(const auto bad:{"OPT CRAM-MD5-0","OPT CRAM-MD5-001122334455667z"}){BinkpOptions o;check(!observe_binkp_information(o,bad,true),"invalid challenge refused");}
}
std::string fixture(){
    // Header fields encoded independently, Type2+, 2:200/10 -> 2:200/11.
    const unsigned char header[58]={10,0,11,0,0xea,7,9,0,29,0,12,0,30,0,15,0,0,0,2,0,200,0,200,0,0xfe,1,
        0,0,0,0,0,0,0,0,2,0,2,0,0,0,0,1,0,0,1,0,2,0,2,0,0,0,0,0,0,0,0,0};
    const unsigned char message[14]={2,0,10,0,11,0,200,0,200,0,1,0,0,0};
    std::string bytes(reinterpret_cast<const char*>(header),58);bytes.append(reinterpret_cast<const char*>(message),14);
    bytes.append("29 Oct 26  12:30:15",19);bytes+='\0';
    for(const auto s:{"Receiver","Writer","Subject","\1INTL 2:200/11 2:200/10\r\1MSGID: 2:200/10 abc123\rHello \x1b[31mred\x1b[0m\r\1X-UNKNOWN keep me"}){bytes+=s;bytes+='\0';}bytes.append(2,'\0');return bytes;
}
void packets(){
    const auto bytes=fixture();const auto decoded=decode_ftn_packet(bytes,"testnet");check(decoded.packet.has_value(),"independent Type2+ fixture parsed");
    const auto& p=*decoded.packet;check(p.header.product==0xfe&&p.header.origin.node==10&&p.header.destination.node==11&&p.messages.size()==1,"packet identity exact");
    const auto metadata=inspect_ftn_message(p.header,p.messages[0]);check(metadata&&metadata->origin.zone==2&&metadata->msgid=="2:200/10 abc123"&&metadata->controls.size()==3,"INTL and retained controls");
    check(encode_ftn_packet(p)==bytes,"packet byte preservation includes ANSI and unknown kludge");
    for(std::size_t n=0;n<bytes.size();++n)check(!decode_ftn_packet(std::string_view(bytes).substr(0,n)).packet,"every truncated packet refused without partial result");
    for(const auto offset:{18U,40U,44U}){auto corrupt=bytes;corrupt[offset]=3;check(!decode_ftn_packet(corrupt).packet,"invalid type/capability refused");}
    check(!decode_ftn_packet(bytes+"x").packet,"no trailing packet injection");
    auto echo=p.messages[0];echo.text="AREA:GENERAL\r\1INTL 8:1/1 8:1/2\rBody\r\1X-KEEP unchanged";
    auto em=inspect_ftn_message(p.header,echo);check(em&&em->area=="GENERAL"&&em->origin.zone==2&&em->origin.node==10,"echomail ignores NetMail address controls");
    echo.text+="\r * Origin: Other zone point (3:400/7.9)\rSEEN-BY: 200/10\r\1PATH: 200/10\r";
    em=inspect_ftn_message(p.header,echo);check(em&&em->origin.zone==3&&em->origin.net==400&&em->origin.node==7&&em->origin.point==9&&em->origin.domain=="testnet","echo source uses retained full Origin address across hub envelope and points");
    echo.text+=" * Origin: Conflicting network (3:400/7.9@other)\r";check(!inspect_ftn_message(p.header,echo),"echo Origin cannot cross configured network domain");
    auto conflict=p.messages[0];conflict.text+="\r\1INTL 2:1/1 2:1/2";check(!inspect_ftn_message(p.header,conflict),"duplicate addressing control refused");
    auto point=p;point.header.origin.point=9;point.header.destination.point=7;const auto packed=encode_ftn_packet(point);check(packed&&decode_ftn_packet(*packed).packet->header.origin.point==9,"Type2+ point fields retained");
    point.header.profile=FtnPacketProfile::type2;check(!encode_ftn_packet(point),"writer refuses losing points in legacy header");
    auto old=p;old.header.profile=FtnPacketProfile::type2;check(encode_ftn_packet(old)&&decode_ftn_packet(*encode_ftn_packet(old)).packet->header.profile==FtnPacketProfile::type2,"legacy Type2 accepted explicitly");
    old.messages[0].text.assign(kFtnMessageMaximumBytes+1,'a');check(!encode_ftn_packet(old),"message source cap before serialization");
}
}
int main(int argc,char** argv){try{framing();descriptors();packets();if(argc==2){std::ifstream file(argv[1],std::ios::binary|std::ios::ate);check(file&&file.tellg()>=0&&file.tellg()<=static_cast<std::streamoff>(kFtnPacketMaximumBytes),"bounded original packet fixture opens");const auto size=static_cast<std::size_t>(file.tellg());file.seekg(0);std::string bytes(size,'\0');file.read(bytes.data(),static_cast<std::streamsize>(size));check(file.good(),"original packet bytes read");const auto result=decode_ftn_packet(bytes,"test-only");if(!result.packet)throw std::runtime_error("original packet: "+result.reason);check(!result.packet->messages.empty(),"original packet messages decoded");std::cout<<"Original fixture: "<<result.packet->messages.size()<<" messages; content/secrets omitted\n";}std::cout<<"PASS "<<checks<<" FTN wire/packet checks\n";return 0;}catch(const std::exception& e){std::cerr<<"FAIL "<<checks<<": "<<e.what()<<'\n';return 1;}}
